queries.sql:
-- 現在の組織の会話を、所有者と開始日時を指定して登録する。
INSERT INTO conversations (id, organization_id, user_id, created_at) VALUES (
    %(id)s, %(organization_id)s, %(user_id)s, %(created_at)s
);

-- 現在の組織に属する指定の添付画像の記録を削除する。
DELETE FROM assets
WHERE organization_id = %(organization_id)s AND id = %(id)s;

-- 現在の組織に属する指定の検索用の文書断片の記録を削除する。
DELETE FROM chunks
WHERE organization_id = %(organization_id)s AND id = %(id)s;

-- 現在の組織に属する指定の下書きの記録を削除する。
DELETE FROM drafts
WHERE organization_id = %(organization_id)s AND id = %(id)s;

-- 現在の組織に属する指定の文字認識の実行記録の記録を削除する。
DELETE FROM ocr_runs
WHERE organization_id = %(organization_id)s AND id = %(id)s;

-- 現在の組織の操作の再送を判定するため、実行済み操作の入力ハッシュと応答を登録する。
INSERT INTO idempotency (id, organization_id, user_id, operation, request_hash, response) VALUES (
    %(id)s, %(organization_id)s, %(user_id)s, %(operation)s, %(request_hash)s, %(response)s
);

-- 組織の改訂番号が一致する場合だけ番号を進め、認可判定と権限失効の競合を検出する。
UPDATE organizations SET revision = revision + 1
WHERE organization_id = %(organization_id)s AND id = %(id)s AND revision = %(revision)s;

-- 現在の組織の部署を、部署名と有効状態を指定して登録する。
INSERT INTO departments (id, organization_id, name, active) VALUES (
    %(id)s, %(organization_id)s, %(name)s, %(active)s
);

-- 組織を、組織名・改訂番号・利用停止状態を指定して登録する。
INSERT INTO organizations (id, organization_id, name, revision, suspended) VALUES (
    %(id)s, %(organization_id)s, %(name)s, %(revision)s, %(suspended)s
);

-- 現在の組織の利用者を、認証主体・表示名・有効状態・運用権限を指定して登録する。
INSERT INTO users (id, organization_id, subject, display_name, active, operator) VALUES (
    %(id)s, %(organization_id)s, %(subject)s, %(display_name)s, %(active)s, %(operator)s
);
